import { readFile } from "node:fs/promises";
import { basename, resolve } from "node:path";
import { parseFrontmatter } from "./frontmatter.js";
import { RESERVED_FILENAMES } from "./spec.js";

export interface InspectReport {
  path: string;
  reserved: boolean;
  hasFrontmatter: boolean;
  frontmatter: Record<string, unknown> | null;
  bodyPreview: string;
  bodyLines: number;
  headings: string[];
  parseError?: string;
  parseLine?: number;
}

export async function inspectFile(filePath: string): Promise<InspectReport> {
  const path = resolve(filePath);
  const content = await readFile(path, "utf8");
  const name = basename(path);
  const reserved = RESERVED_FILENAMES.has(name);
  const parsed = parseFrontmatter(content);

  if (!parsed.ok) {
    return {
      path,
      reserved,
      hasFrontmatter: parsed.hasFrontmatter,
      frontmatter: null,
      bodyPreview: content.slice(0, 400),
      bodyLines: content.split(/\r?\n/).length,
      headings: extractHeadings(content),
      parseError: parsed.error,
      parseLine: parsed.line,
    };
  }

  const body = parsed.content;
  return {
    path,
    reserved,
    hasFrontmatter: parsed.hasFrontmatter,
    frontmatter: parsed.hasFrontmatter ? parsed.data : null,
    bodyPreview: body.slice(0, 400).trimEnd(),
    bodyLines: body.split(/\r?\n/).length,
    headings: extractHeadings(body),
  };
}

function extractHeadings(body: string): string[] {
  const headings: string[] = [];
  for (const line of body.split(/\r?\n/)) {
    const m = line.match(/^(#{1,6})\s+(.+)$/);
    if (m) headings.push(`${m[1]} ${m[2].trim()}`);
  }
  return headings;
}

export function formatInspectReport(report: InspectReport, json = false): string {
  if (json) return JSON.stringify(report, null, 2);

  const lines: string[] = [
    `File: ${report.path}`,
    `Reserved: ${report.reserved ? "yes" : "no"}`,
    `Frontmatter: ${report.hasFrontmatter ? "yes" : "no"}`,
  ];

  if (report.parseError) {
    lines.push(
      `Parse error${report.parseLine !== undefined ? ` at line ${report.parseLine}` : ""}: ${report.parseError}`,
    );
  }

  if (report.frontmatter) {
    lines.push("Frontmatter fields:");
    for (const [key, value] of Object.entries(report.frontmatter)) {
      lines.push(`  ${key}: ${JSON.stringify(value)}`);
    }
  }

  lines.push(`Body lines: ${report.bodyLines}`);
  if (report.headings.length > 0) {
    lines.push("Headings:");
    for (const h of report.headings) lines.push(`  ${h}`);
  }

  if (report.bodyPreview) {
    lines.push("--- body preview ---");
    lines.push(report.bodyPreview);
  }

  return lines.join("\n");
}
